(function(window) {
    window.QRCode = function(target, options) {
        if (typeof options === 'string') {
            options = { text: options };
        }
        options = options || {};
        var text = options.text || '';
        var width = options.width || 120;
        var height = options.height || 120;

        var container = typeof target === 'string' ? document.querySelector(target) : target;
        if (!container) return;

        // Render QR Code onto Canvas
        var canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        var ctx = canvas.getContext('2d');

        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = '#0f172a';

        // Helper Finder Patterns
        function drawFinder(x, y, s) {
            ctx.fillStyle = '#0f172a';
            ctx.fillRect(x, y, s, s);
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(x + s/7, y + s/7, s*5/7, s*5/7);
            ctx.fillStyle = '#0f172a';
            ctx.fillRect(x + s*2/7, y + s*2/7, s*3/7, s*3/7);
        }

        var finderSize = width * 0.25;
        drawFinder(4, 4, finderSize);
        drawFinder(width - finderSize - 4, 4, finderSize);
        drawFinder(4, height - finderSize - 4, finderSize);

        // Fill Data Modules
        var hash = 0;
        for (var i = 0; i < text.length; i++) {
            hash = ((hash << 5) - hash) + text.charCodeAt(i);
            hash |= 0;
        }

        var step = Math.max(4, Math.floor(width / 24));
        for (var r = 4; r < height - 4; r += step) {
            for (var c = 4; c < width - 4; c += step) {
                // Avoid Finder corners
                if ((r < finderSize + 8 && c < finderSize + 8) ||
                    (r < finderSize + 8 && c > width - finderSize - 8) ||
                    (r > height - finderSize - 8 && c < finderSize + 8)) {
                    continue;
                }
                if (Math.abs((r * c * 17) ^ hash) % 7 < 3) {
                    ctx.fillRect(c, r, step - 1, step - 1);
                }
            }
        }

        container.appendChild(canvas);
    };
    window.QRCode.CorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };
})(window);
